// Quiz logic. Question data lives in questions.js (auto-generated by backend.py).
// The `questions` global is expected to be defined by questions.js, loaded before this file.


// ---------------------------------------------------------------------------
// API routing
// Talks to server.py. By default API requests use same-origin when hosted
// (e.g. Render), and fallback to http://127.0.0.1:5001 for local file:// use.
// Override by setting window.QUIZ_API_BASE before this script.
// ---------------------------------------------------------------------------
const QUIZ_API_DEFAULT_HOSTS = ['127.0.0.1:5001', 'localhost:5001'];
const QUIZ_API_DEFAULT_BASE = 'http://127.0.0.1:5001';

function quizApiUrl(path) {
    let base = (typeof window !== 'undefined') ? window.QUIZ_API_BASE : undefined;
    if (typeof base !== 'string') {
        const onFlask = typeof window !== 'undefined'
            && QUIZ_API_DEFAULT_HOSTS.indexOf(window.location.host) !== -1;
        if (onFlask) {
            base = '';
        } else if (typeof window !== 'undefined' && window.location.protocol === 'file:') {
            base = QUIZ_API_DEFAULT_BASE;
        } else if (typeof window !== 'undefined'
            && (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1')) {
            base = window.location.protocol + '//' + window.location.hostname + ':5001';
        } else {
            base = window.location.origin;
        }
    }
    return base.replace(/\/$/, '') + path;
}


// ===========================================================================
// QSetStore — PostgreSQL-backed persistence for the signed-in user.
//
// The store keeps an in-memory cache hydrated from the API on sign-in so the
// rest of the app can keep calling `QSetStore.list()` / `.get(id)` etc.
// synchronously. Mutations write through to the API in the background; the
// cache is the read source of truth.
//
// Endpoints (all session-cookie authenticated, scoped server-side by user id):
//   GET    /api/sets             → list user's set summaries
//   GET    /api/sets/<id>        → full record
//   POST   /api/sets             → upsert
//   DELETE /api/sets/<id>        → remove
//   POST   /api/sets/<id>/stats  → record a practice score
//   GET/PUT /api/active-set      → which set drives the quiz
// ===========================================================================
const QSetStore = (function () {
    const SCHEMA_VERSION = 1;

    // In-memory cache. Hydrated on sign-in via QSetStore.bootstrap().
    const cache = {
        summaries: [],          // [{ id, title, ... }]
        fullRecords: new Map(), // id → full record (lazy-loaded)
        activeId: null,
        ready: false,
    };

    function fetchJSON(url, opts) {
        const o = Object.assign({ credentials: 'include' }, opts || {});
        if (o.body && !(o.body instanceof FormData)) {
            o.headers = Object.assign({ 'Content-Type': 'application/json' }, o.headers || {});
        }
        return fetch(quizApiUrl(url), o).then(async (r) => {
            const text = await r.text();
            let data = null;
            try { data = text ? JSON.parse(text) : null; } catch (_) { /* non-JSON */ }
            return { ok: r.ok, status: r.status, data, text };
        });
    }

    function newId() {
        // Server can also issue an id; this is for clients that need one upfront.
        return 'qs_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
    }

    async function bootstrap() {
        const [setsRes, activeRes] = await Promise.all([
            fetchJSON('/api/sets'),
            fetchJSON('/api/active-set'),
        ]);
        if (setsRes.ok && setsRes.data && Array.isArray(setsRes.data.sets)) {
            cache.summaries = setsRes.data.sets;
        } else {
            cache.summaries = [];
        }
        if (activeRes.ok && activeRes.data) {
            cache.activeId = activeRes.data.activeId || null;
        } else {
            cache.activeId = null;
        }
        cache.fullRecords.clear();
        cache.ready = true;
    }

    function reset() {
        cache.summaries = [];
        cache.fullRecords.clear();
        cache.activeId = null;
        cache.ready = false;
    }

    function list() {
        return cache.summaries.slice();
    }

    function get(id) {
        if (!id) return null;
        // Synchronous reads come from cache; full records get lazy-loaded
        // asynchronously by `loadFull` (used in hydration) — see Cert.js init.
        return cache.fullRecords.get(id) || null;
    }

    async function loadFull(id) {
        if (!id) return null;
        if (cache.fullRecords.has(id)) return cache.fullRecords.get(id);
        const res = await fetchJSON('/api/sets/' + encodeURIComponent(id));
        if (!res.ok || !res.data || !res.data.set) return null;
        cache.fullRecords.set(id, res.data.set);
        return res.data.set;
    }

    function _upsertSummaryFromRecord(record) {
        const summary = {
            id: record.id,
            title: record.title,
            createdAt: record.createdAt,
            updatedAt: record.updatedAt,
            questionCount: record.questionCount,
            sourceFilename: (record.source && record.source.filename) || null,
            lastPlayedAt: (record.stats && record.stats.lastPlayedAt) || null,
            bestScore: (record.stats && record.stats.bestScore != null) ? record.stats.bestScore : null,
        };
        const i = cache.summaries.findIndex(s => s.id === record.id);
        if (i >= 0) cache.summaries[i] = summary;
        else cache.summaries.unshift(summary);
        cache.fullRecords.set(record.id, record);
    }

    function save(record) {
        // Synchronous-looking API: optimistically update cache, then sync the API.
        if (!record || typeof record !== 'object') return null;
        record.schemaVersion = record.schemaVersion || SCHEMA_VERSION;
        record.id = record.id || newId();
        record.createdAt = record.createdAt || new Date().toISOString();
        record.updatedAt = new Date().toISOString();
        record.questions = Array.isArray(record.questions) ? record.questions : [];
        record.questionCount = record.questions.length;
        record.stats = record.stats || { sessionsRun: 0, lastPlayedAt: null, bestScore: null, averageScore: null };

        _upsertSummaryFromRecord(record);

        fetchJSON('/api/sets', {
            method: 'POST',
            body: JSON.stringify({
                id: record.id,
                title: record.title,
                source: record.source || {},
                questions: record.questions,
                stats: record.stats,
            }),
        }).then((res) => {
            if (!res.ok) console.warn('[QSetStore] save failed:', res.status, res.data && res.data.error);
            else if (res.data && res.data.set) {
                // Re-sync cache with server-canonical record (updates timestamps).
                _upsertSummaryFromRecord(res.data.set);
            }
        }).catch((e) => console.warn('[QSetStore] save network error:', e));

        return record;
    }

    function del(id) {
        if (!id) return;
        cache.summaries = cache.summaries.filter(s => s.id !== id);
        cache.fullRecords.delete(id);
        if (cache.activeId === id) cache.activeId = null;
        fetchJSON('/api/sets/' + encodeURIComponent(id), { method: 'DELETE' })
            .catch((e) => console.warn('[QSetStore] delete network error:', e));
    }

    function getActiveId() {
        return cache.activeId || null;
    }
    function setActiveId(id) {
        cache.activeId = id || null;
        fetchJSON('/api/active-set', {
            method: 'PUT',
            body: JSON.stringify({ activeId: id || null }),
        }).catch((e) => console.warn('[QSetStore] setActive network error:', e));
    }

    function updateStats(id, finalScorePct) {
        // Optimistic local update for snappy UI; server is the source of truth.
        const record = cache.fullRecords.get(id);
        if (record && record.stats) {
            const s = record.stats;
            const prevAvg = s.averageScore;
            s.sessionsRun = (s.sessionsRun || 0) + 1;
            s.lastPlayedAt = new Date().toISOString();
            s.bestScore = (s.bestScore == null) ? finalScorePct : Math.max(s.bestScore, finalScorePct);
            s.averageScore = (prevAvg == null)
                ? finalScorePct
                : Math.round(((prevAvg * (s.sessionsRun - 1)) + finalScorePct) / s.sessionsRun);
            _upsertSummaryFromRecord(record);
        }
        fetchJSON('/api/sets/' + encodeURIComponent(id) + '/stats', {
            method: 'POST',
            body: JSON.stringify({ score: finalScorePct }),
        }).catch((e) => console.warn('[QSetStore] stats network error:', e));
    }

    // pendingSave is no longer needed (server saves directly), but the methods
    // remain as no-ops so any older callers keep working without errors.
    function getPendingSave() { return null; }
    function setPendingSave() { /* no-op */ }
    function clearPendingSave() { /* no-op */ }

    return {
        SCHEMA_VERSION,
        newId, list, get, save, loadFull,
        delete: del,
        getActiveId, setActiveId,
        getPendingSave, setPendingSave, clearPendingSave,
        updateStats,
        bootstrap, reset,
        _cache: cache,
    };
})();


// ===========================================================================
// Auth flow — overlay, sign in/up, sign out.
// ===========================================================================
let currentUser = null;
let authMode = 'signin'; // 'signin' | 'signup'

function isGenerationLimitReached() {
    const usage = currentUser && currentUser.usage;
    if (!usage) return false;
    const used = Number(usage.generationsUsed || 0);
    const limit = Number(usage.generationsLimit || 0);
    return limit > 0 && used >= limit;
}

function usageBadgeText() {
    const usage = currentUser && currentUser.usage;
    if (!usage) return '';
    const tier = (currentUser.planTier || usage.planTier || 'free').toUpperCase();
    const used = Number(usage.generationsUsed || 0);
    const limit = Number(usage.generationsLimit || 0);
    return tier + ' ' + used + '/' + limit + ' generations';
}

function _authFetch(url, opts) {
    const o = Object.assign({ credentials: 'include' }, opts || {});
    if (o.body && !(o.body instanceof FormData)) {
        o.headers = Object.assign({ 'Content-Type': 'application/json' }, o.headers || {});
    }
    return fetch(quizApiUrl(url), o).then(async (r) => {
        const text = await r.text();
        let data = null;
        try { data = text ? JSON.parse(text) : null; } catch (_) {}
        return { ok: r.ok, status: r.status, data };
    });
}

function setAuthMode(mode) {
    authMode = (mode === 'signup') ? 'signup' : 'signin';
    const tabIn = document.getElementById('authTabSignIn');
    const tabUp = document.getElementById('authTabSignUp');
    const emailField = document.getElementById('authEmailField');
    const submitBtn = document.getElementById('authSubmitBtn');
    const title = document.getElementById('authTitle');
    const subtitle = document.getElementById('authSubtitle');
    const passwordInput = document.getElementById('authPassword');

    if (tabIn && tabUp) {
        tabIn.classList.toggle('auth-tab--active', authMode === 'signin');
        tabUp.classList.toggle('auth-tab--active', authMode === 'signup');
        tabIn.setAttribute('aria-selected', authMode === 'signin' ? 'true' : 'false');
        tabUp.setAttribute('aria-selected', authMode === 'signup' ? 'true' : 'false');
    }
    if (emailField) emailField.style.display = authMode === 'signup' ? 'flex' : 'none';
    if (submitBtn) submitBtn.textContent = authMode === 'signup' ? 'Create account' : 'Sign in';
    if (title) title.textContent = authMode === 'signup' ? 'Create your account' : 'Sign in to continue';
    if (subtitle) subtitle.textContent = authMode === 'signup'
        ? 'Your question sets and history will be stored under your account.'
        : 'Your question sets and history stay with your account.';
    if (passwordInput) passwordInput.setAttribute('autocomplete', authMode === 'signup' ? 'new-password' : 'current-password');
    setAuthStatus('', '');
}

function setAuthStatus(text, kind) {
    const el = document.getElementById('authStatus');
    if (!el) return;
    if (!text) {
        el.style.display = 'none';
        el.textContent = '';
        el.className = 'upload-status';
        return;
    }
    el.textContent = text;
    el.className = 'upload-status ' + (kind || '');
    el.style.display = 'block';
}

async function submitAuth() {
    const username = (document.getElementById('authUsername').value || '').trim();
    const password = document.getElementById('authPassword').value || '';
    const email = (document.getElementById('authEmail').value || '').trim();
    const submitBtn = document.getElementById('authSubmitBtn');

    if (!username || !password) {
        setAuthStatus('Username and password are required.', 'error');
        return;
    }

    if (submitBtn) submitBtn.disabled = true;
    setAuthStatus(authMode === 'signup' ? 'Creating your account…' : 'Signing in…', 'loading');

    const url = authMode === 'signup' ? '/api/auth/register' : '/api/auth/login';
    const body = authMode === 'signup' ? { username, password, email } : { username, password };
    const res = await _authFetch(url, { method: 'POST', body: JSON.stringify(body) });

    if (!res.ok || !res.data || !res.data.ok) {
        const msg = (res.data && res.data.error) || ('Failed (HTTP ' + res.status + ')');
        setAuthStatus(msg, 'error');
        if (submitBtn) submitBtn.disabled = false;
        return;
    }

    currentUser = res.data.user;
    setAuthStatus('Welcome, ' + currentUser.username + '!', 'success');
    if (submitBtn) submitBtn.disabled = false;
    await onSignedIn();
}

async function signOut() {
    await _authFetch('/api/auth/logout', { method: 'POST' });
    currentUser = null;
    QSetStore.reset();
    // Reset the in-memory quiz state so nothing leaks into the next user.
    try { localStorage.removeItem('examSessionData'); } catch (_) {}
    // Clean reload puts us back at the auth overlay, with a fresh page.
    window.location.reload();
}

async function checkAuthOnLoad() {
    const res = await _authFetch('/api/auth/me');
    if (res.ok && res.data && res.data.ok && res.data.user) {
        currentUser = res.data.user;
        await onSignedIn();
    } else {
        showAuthOverlay();
    }
}

function showAuthOverlay() {
    const overlay = document.getElementById('authOverlay');
    if (overlay) overlay.style.display = 'flex';
    const pill = document.getElementById('userPill');
    if (pill) pill.style.display = 'none';
    const dashboard = document.getElementById('dashboard');
    if (dashboard) dashboard.style.display = 'none';
}

function hideAuthOverlay() {
    const overlay = document.getElementById('authOverlay');
    if (overlay) overlay.style.display = 'none';
    const dashboard = document.getElementById('dashboard');
    if (dashboard) dashboard.style.display = 'block';
}

function paintUserPill() {
    const pill = document.getElementById('userPill');
    const name = document.getElementById('userPillName');
    const usage = document.getElementById('userPlanUsage');
    if (pill && currentUser) {
        pill.style.display = 'inline-flex';
        if (name) name.textContent = currentUser.username;
        if (usage) {
            const txt = usageBadgeText();
            usage.style.display = txt ? 'inline-flex' : 'none';
            usage.textContent = txt;
        }
    }
}

async function onSignedIn() {
    paintUserPill();
    hideAuthOverlay();

    // Pull this user's saved sets + active set + history from the server
    // before hydrating the quiz, so nothing from the previous user leaks through.
    try {
        await Promise.all([
            QSetStore.bootstrap(),
            bootstrapSessionHistory(),
        ]);
    } catch (e) {
        console.warn('[auth] bootstrap failed:', e);
    }

    // If there's an active set, fetch its full record + swap into `questions`.
    const activeId = QSetStore.getActiveId();
    if (activeId) {
        try {
            const full = await QSetStore.loadFull(activeId);
            if (full && Array.isArray(full.questions) && full.questions.length) {
                replaceLoadedQuestions(full.questions);
            }
        } catch (e) {
            console.warn('[auth] active set hydrate failed:', e);
        }
    }

    // Refresh dashboard widgets that read from server-cached data.
    try { renderQuestionSets(); } catch (_) {}
    try { renderSessionHistory(); } catch (_) {}
}


// Global variables
let selectedTrainingTime = 60; // Default time
let isTimeSet = false;
let currentQuestion = 0;
let userAnswers = {};
let timeLeft = 3600;
let timerInterval;
let isTrainingMode = false;
let isUnlimitedTime = false;
let sessionActive = false;
let selectedMode = null; // 'exam' | 'training' | null

// ---------------------------------------------------------------------------
// Two-step mode selection: pick a mode card, then click Start.
// ---------------------------------------------------------------------------
function selectMode(mode) {
    if (mode !== 'exam' && mode !== 'training') return;
    selectedMode = mode;

    const examCard = document.getElementById('examModeCard');
    const trainingCard = document.getElementById('startTrainingBtn'); // legacy id kept for backwards compat
    if (examCard) {
        examCard.classList.toggle('mode-card--selected', mode === 'exam');
        examCard.setAttribute('aria-checked', mode === 'exam' ? 'true' : 'false');
    }
    if (trainingCard) {
        trainingCard.classList.toggle('mode-card--selected', mode === 'training');
        trainingCard.setAttribute('aria-checked', mode === 'training' ? 'true' : 'false');
    }

    const trainingOptions = document.getElementById('trainingOptions');
    if (trainingOptions) {
        trainingOptions.style.display = mode === 'training' ? 'block' : 'none';
    }

    // When Training is picked, seed isTimeSet from the current input so Start works immediately.
    if (mode === 'training') {
        const input = document.getElementById('timeLimit');
        const minutes = parseInt(input && input.value, 10);
        selectedTrainingTime = (Number.isFinite(minutes) && minutes > 0) ? minutes : 60;
        isTimeSet = true;
    }

    const startBtn = document.getElementById('startSelectedBtn');
    const startLabel = document.getElementById('startSelectedLabel');
    if (startBtn) {
        const wasHidden = startBtn.style.display === 'none' || !startBtn.style.display;
        startBtn.style.display = 'inline-flex';
        startBtn.classList.toggle('btn--primary', mode === 'exam');
        startBtn.classList.toggle('btn--accent', mode === 'training');
        // Retrigger reveal animation only on first reveal, not on every mode switch.
        if (wasHidden) {
            startBtn.classList.remove('start-selected-btn--in');
            // Force reflow so the animation restarts cleanly.
            // eslint-disable-next-line no-unused-expressions
            void startBtn.offsetWidth;
            startBtn.classList.add('start-selected-btn--in');
        }
    }
    if (startLabel) {
        startLabel.textContent = mode === 'exam' ? 'Start Exam' : 'Start Training';
    }
}

function clearModeSelection() {
    selectedMode = null;
    const examCard = document.getElementById('examModeCard');
    const trainingCard = document.getElementById('startTrainingBtn');
    if (examCard) {
        examCard.classList.remove('mode-card--selected');
        examCard.setAttribute('aria-checked', 'false');
    }
    if (trainingCard) {
        trainingCard.classList.remove('mode-card--selected');
        trainingCard.setAttribute('aria-checked', 'false');
    }
    const trainingOptions = document.getElementById('trainingOptions');
    if (trainingOptions) trainingOptions.style.display = 'none';
    const startBtn = document.getElementById('startSelectedBtn');
    if (startBtn) {
        startBtn.style.display = 'none';
        startBtn.classList.remove('start-selected-btn--in');
    }
}

function startSelectedMode() {
    if (selectedMode === 'exam') {
        startExamMode();
    } else if (selectedMode === 'training') {
        beginTraining();
    }
}

// Kept for backwards compatibility — any old caller now just selects Training.
function showTrainingOptions() {
    selectMode('training');
}

function startExamMode() {
    isTrainingMode = false;
    timeLeft = 7200; // 2 hours in seconds
    sessionActive = true;
    document.getElementById('dashboard').style.display = 'none';
    document.getElementById('examContainer').style.display = 'block';
    document.getElementById('modeTitle').textContent = 'Exam Mode';
    document.getElementById('trainingFeedback').style.display = 'none';
    initializeExam();
}

function setTrainingTime() {
    const minutes = parseInt(document.getElementById('timeLimit').value, 10) || 60;
    if (minutes < 1) {
        alert('Please enter a time of at least 1 minute');
        return;
    }
    selectedTrainingTime = minutes;
    isTimeSet = true;
    isUnlimitedTime = false;
}

function setUnlimitedTime() {
    selectedTrainingTime = 999999; // Very high number for "unlimited"
    isTimeSet = true;
    isUnlimitedTime = true;
}

function beginTraining() {
    if (!isTimeSet) {
        alert('Please set a time limit first');
        return;
    }

    isTrainingMode = true;
    isUnlimitedTime = (selectedTrainingTime === 999999);
    sessionActive = true;
    timeLeft = selectedTrainingTime * 60;

    document.getElementById('dashboard').style.display = 'none';
    document.getElementById('examContainer').style.display = 'block';
    document.getElementById('modeTitle').textContent = 'Training Mode';
    document.getElementById('trainingFeedback').style.display = 'none';

    initializeExam();
}

function startTrainingMode(unlimited) {
    isTrainingMode = true;
    isUnlimitedTime = unlimited;
    sessionActive = true;
    
    if (unlimited) {
        timeLeft = 999999; // Very high number for "unlimited"
    } else {
        const minutes = parseInt(document.getElementById('timeLimit').value) || 60;
        timeLeft = minutes * 60;
    }
    
    document.getElementById('dashboard').style.display = 'none';
    document.getElementById('examContainer').style.display = 'block';
    document.getElementById('modeTitle').textContent = 'Training Mode';
    initializeExam();
}

function continueSession() {
    // Resume from saved session
    const savedData = JSON.parse(localStorage.getItem('examSessionData') || '{}');
    if (savedData && savedData.sessionActive) {
        currentQuestion = savedData.currentQuestion || 0;
        userAnswers = savedData.userAnswers || {};
        timeLeft = savedData.timeLeft || 3600;
        isTrainingMode = savedData.isTrainingMode || false;
        isUnlimitedTime = savedData.isUnlimitedTime || false;
        sessionActive = true;
        document.getElementById('dashboard').style.display = 'none';
        document.getElementById('examContainer').style.display = 'block';
        document.getElementById('modeTitle').textContent = isTrainingMode ? 'Training Mode' : 'Exam Mode';
        document.getElementById('trainingFeedback').style.display = 'none';
        initializeExam();
    }
}

function resetSession() {
    clearInterval(timerInterval);
    clearStorage();
    currentQuestion = 0;
    userAnswers = {};
    timeLeft = 3600;
    sessionActive = false;
    document.getElementById('continueButton').style.display = 'none';
    const incompleteNotice = document.getElementById('incompleteSessionNotice');
    if (incompleteNotice) incompleteNotice.style.display = 'none';
    clearModeSelection();
    alert('Session has been reset');
}

function backToDashboard() {
    saveToStorage();
    document.getElementById('dashboard').style.display = 'block';
    document.getElementById('examContainer').style.display = 'none';
    document.getElementById('results').style.display = 'none';
    document.getElementById('examContent').style.display = 'block';
    clearModeSelection();
    // Reflect any stats changes that happened during the session.
    try { renderQuestionSets(); } catch (_) { /* render is optional */ }
}

// Initialize the exam screen.
// IMPORTANT: do NOT re-read examSessionData here. Both callers already set
// the relevant state themselves:
//   - startExamMode / beginTraining set isTrainingMode + sessionActive fresh
//   - continueSession restores isTrainingMode + the rest from storage explicitly
// Re-reading storage in this function used to clobber a freshly-set
// isTrainingMode=true with a stale `false` left over from a previous Exam
// session, which broke training-mode feedback on every fresh Training start
// until the user manually clicked Reset Session.
function initializeExam() {
    // Initialize userAnswers for any questions that don't have an entry yet.
    if (typeof questions !== 'undefined') {
        questions.forEach((question, index) => {
            if (!userAnswers[index]) {
                userAnswers[index] = question.maxSelections > 1 ? [] : [];
            }
        });
    }
    
    if (document.getElementById('continueButton')) {
        document.getElementById('continueButton').style.display = sessionActive ? 'block' : 'none';
    }
    
    displayQuestion();
    startTimer();
    updateProgress();
}

// Modified displayQuestion to show feedback in training mode
function displayQuestion() {
    if (typeof questions === 'undefined' || !questions[currentQuestion]) return;
    
    const question = questions[currentQuestion];
    const maxSelections = question.maxSelections || 1;
    
    document.getElementById('questionNumber').textContent = `Question ${currentQuestion + 1} of ${questions.length}`;
    
    // Add instruction about multiple selections
    let instructionText = question.text;
    if (maxSelections > 1) {
        instructionText += `\n\n(Select ${maxSelections} answers)`;
    }
    document.getElementById('questionText').innerText = instructionText;
    
    const choicesContainer = document.getElementById('choices');
    choicesContainer.innerHTML = '';
    
    Object.entries(question.choices).forEach(([key, value]) => {
        const choiceDiv = document.createElement('div');
        choiceDiv.className = 'choice';
        choiceDiv.dataset.choiceKey = key;
        choiceDiv.onclick = () => selectAnswer(key);

        choiceDiv.innerHTML = `
            <div class="choice-label">${key}</div>
            <div class="choice-content">${value}</div>
        `;
        choicesContainer.appendChild(choiceDiv);
    });

    // Paint .selected from the data, not from the click event — keeps the
    // visual state in lockstep with userAnswers across re-renders.
    refreshChoiceSelection();

    // Training mode: also paint per-option correct/incorrect feedback so the
    // right answer is visible on the option card itself, immediately, with no
    // dashboard or reset-session detour. This is the missing refresh step.
    if (isTrainingMode && userAnswers[currentQuestion] && userAnswers[currentQuestion].length > 0) {
        applyTrainingFeedback();
        showQuestionFeedback();
    } else if (isTrainingMode && document.getElementById('trainingFeedback')) {
        document.getElementById('trainingFeedback').style.display = 'none';
    }

    updateNavigationButtons();
}

// Repaint .selected on every choice card from userAnswers. No reliance on the
// click event target — so navigation, re-renders, and programmatic changes all
// stay in sync with the underlying data.
function refreshChoiceSelection() {
    const choicesContainer = document.getElementById('choices');
    if (!choicesContainer) return;
    const userAnswer = userAnswers[currentQuestion] || [];
    const userSet = new Set(Array.isArray(userAnswer) ? userAnswer : [userAnswer]);
    choicesContainer.querySelectorAll('.choice').forEach((el) => {
        const key = el.dataset.choiceKey;
        el.classList.toggle('selected', userSet.has(key));
    });
}

// Training-mode per-option highlight: green check on correct answers, red X on
// the user's incorrect picks. Called after every answer change and after every
// re-render so the right option is visible on the card itself the moment it's
// known — not buried in a text line below.
function applyTrainingFeedback() {
    const choicesContainer = document.getElementById('choices');
    if (!choicesContainer) return;

    // Always clear stale state first.
    choicesContainer.querySelectorAll('.choice').forEach((el) => {
        el.classList.remove('choice--correct', 'choice--incorrect');
    });

    if (!isTrainingMode) return;
    const question = questions && questions[currentQuestion];
    if (!question) return;
    const userAnswer = userAnswers[currentQuestion] || [];
    if (!userAnswer.length) return;

    const correctRaw = question.answer;
    const correctSet = new Set(Array.isArray(correctRaw) ? correctRaw : [correctRaw]);
    const userSet = new Set(userAnswer);

    choicesContainer.querySelectorAll('.choice').forEach((el) => {
        const key = el.dataset.choiceKey;
        if (correctSet.has(key)) {
            el.classList.add('choice--correct');
        } else if (userSet.has(key)) {
            el.classList.add('choice--incorrect');
        }
    });
}

function selectAnswer(choice) {
    if (typeof questions === 'undefined' || !questions[currentQuestion]) return;

    const question = questions[currentQuestion];
    const maxSelections = question.maxSelections || 1;

    if (!userAnswers[currentQuestion]) {
        userAnswers[currentQuestion] = [];
    }

    const currentAnswers = userAnswers[currentQuestion];
    const choiceIndex = currentAnswers.indexOf(choice);

    if (choiceIndex > -1) {
        // Toggle off
        currentAnswers.splice(choiceIndex, 1);
    } else if (currentAnswers.length < maxSelections) {
        currentAnswers.push(choice);
    } else {
        alert(`You can only select ${maxSelections} answers.`);
        return;
    }

    // Single source of truth: rebuild the visual state from userAnswers.
    refreshChoiceSelection();

    if (isTrainingMode) {
        // Immediately recompute and paint the correct/incorrect option styling.
        // This is the fix: previously only the text below was updated; the
        // option cards never got a result class, so the correct answer was
        // never visually highlighted on the card itself.
        applyTrainingFeedback();
        showQuestionFeedback();
    }

    saveToStorage();
}

// New function to show feedback for current question (training mode)
function showQuestionFeedback() {
    if (!isTrainingMode || !document.getElementById('trainingFeedback')) return;
    
    const question = questions[currentQuestion];
    const feedbackDiv = document.getElementById('trainingFeedback');
    const userAnswer = userAnswers[currentQuestion] || [];
    const correctAnswer = question.answer;
    
    let isCorrect;
    if (Array.isArray(correctAnswer)) {
        const sortedUser = [...userAnswer].sort();
        const sortedCorrect = [...correctAnswer].sort();
        isCorrect = JSON.stringify(sortedUser) === JSON.stringify(sortedCorrect);
    } else {
        isCorrect = userAnswer[0] === correctAnswer;
    }
    
    feedbackDiv.innerHTML = `
        <div style="margin-bottom: 10px; color: ${isCorrect ? '#28a745' : '#dc3545'}; font-weight: bold;">
            ${isCorrect ? '✓ Correct!' : '✗ Incorrect'}
        </div>
        <div>Your answer: ${userAnswer.length > 0 ? userAnswer.join(', ') : 'Not answered'}</div>
        <div>Correct answer: ${Array.isArray(correctAnswer) ? correctAnswer.join(', ') : correctAnswer}</div>
    `;
    feedbackDiv.style.display = 'block';
}

function nextQuestion() {
    if (typeof questions !== 'undefined' && currentQuestion < questions.length - 1) {
        currentQuestion++;
        displayQuestion();
        updateProgress();
    }
}

function previousQuestion() {
    if (currentQuestion > 0) {
        currentQuestion--;
        displayQuestion();
        updateProgress();
    }
}

function updateNavigationButtons() {
    const prevButton = document.getElementById('prevButton');
    const nextButton = document.getElementById('nextButton');
    const submitButton = document.getElementById('submitButton');
    
    if (prevButton) prevButton.disabled = currentQuestion === 0;
    if (nextButton) nextButton.style.display = (typeof questions !== 'undefined' && currentQuestion === questions.length - 1) ? 'none' : 'inline-block';
    if (submitButton) submitButton.style.display = (typeof questions !== 'undefined' && currentQuestion === questions.length - 1) ? 'inline-block' : 'none';
}

function updateProgress() {
    if (typeof questions === 'undefined') return;
    
    const progress = Math.round(((currentQuestion + 1) / questions.length) * 100);
    const progressBar = document.getElementById('progressBar');
    if (progressBar) {
        progressBar.style.width = `${progress}%`;
    }
}

function startTimer() {
    if (timerInterval) clearInterval(timerInterval);
    
    timerInterval = setInterval(() => {
        if (!isUnlimitedTime) {
            timeLeft--;
            updateTimerDisplay();
            
            if (timeLeft <= 0) {
                clearInterval(timerInterval);
                submitExam();
            }
        } else {
            updateTimerDisplay();
        }
    }, 1000);
}

function updateTimerDisplay() {
    const timerElement = document.getElementById('timer');
    if (!timerElement) return;
    
    if (isUnlimitedTime) {
        timerElement.textContent = 'Unlimited';
        timerElement.style.color = '';
        return;
    }
    
    const minutes = Math.floor(timeLeft / 60);
    const seconds = timeLeft % 60;
    const timerDisplay = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    timerElement.textContent = timerDisplay;
    
    // Change color when time is running low
    if (timeLeft <= 300) { // 5 minutes
        timerElement.style.color = '#ff4444';
    } else if (timeLeft <= 600) { // 10 minutes
        timerElement.style.color = '#ff8800';
    } else {
        timerElement.style.color = '';
    }
}

// Modified submitExam to handle training mode feedback
function submitExam() {
    clearInterval(timerInterval);
    calculateScore();

    // Save session result to history
    const correct = typeof lastScoreCorrectCount !== 'undefined' ? lastScoreCorrectCount : 0;
    const total = typeof questions !== 'undefined' ? questions.length : 0;
    const percentage = total ? Math.round((correct / total) * 100) : 0;
    const mode = isTrainingMode ? 'Training' : 'Exam';
    const now = new Date();
    const dateStr = now.toLocaleString();
    saveSessionHistory({
        mode: mode,
        score: percentage,
        correct: correct,
        total: total,
        date: dateStr
    });

    // Roll the per-set stats forward so the Question sets card shows progress.
    try {
        const activeSetId = QSetStore.getActiveId();
        if (activeSetId) QSetStore.updateStats(activeSetId, percentage);
    } catch (_) { /* localStorage may be disabled */ }

    if (isTrainingMode) {
        showFullscreenFeedback();
    } else {
        showResults();
    }

    sessionActive = false;
    saveToStorage();
    renderSessionHistory();
}

function calculateScore() {
    if (typeof questions === 'undefined') return;

    let correctCount = 0;
    const totalQuestions = questions.length;

    questions.forEach((question, index) => {
        const userAnswer = userAnswers[index] || [];
        const correctAnswer = question.answer;

        // Compare arrays for multiple choice questions
        if (Array.isArray(correctAnswer)) {
            const sortedUserAnswer = [...userAnswer].sort();
            const sortedCorrectAnswer = [...correctAnswer].sort();

            if (JSON.stringify(sortedUserAnswer) === JSON.stringify(sortedCorrectAnswer)) {
                correctCount++;
            }
        } else {
            if (userAnswer[0] === correctAnswer) {
                correctCount++;
            }
        }
    });

    lastScoreCorrectCount = correctCount;

    const percentage = Math.round((correctCount / totalQuestions) * 100);
    const incorrectCount = totalQuestions - correctCount;
    
    // Update score display
    const correctCountEl = document.getElementById('correctCount');
    const incorrectCountEl = document.getElementById('incorrectCount');
    const finalScoreEl = document.getElementById('finalScore');
    const scorePercentageEl = document.getElementById('scorePercentage');
    
    if (correctCountEl) correctCountEl.textContent = correctCount;
    if (incorrectCountEl) incorrectCountEl.textContent = incorrectCount;
    if (finalScoreEl) finalScoreEl.textContent = `${percentage}%`;
    if (scorePercentageEl) {
        scorePercentageEl.innerHTML = `
            <div style="font-size: 4rem; font-weight: bold; color: ${percentage >= 70 ? '#4CAF50' : '#f44336'}">
                ${percentage}%
            </div>
            <div style="font-size: 1.2rem; margin-top: 10px;">
                ${percentage >= 70 ? 'Congratulations! You passed!' : 'Better luck next time!'}
            </div>
        `;
    }
    
    generateQuestionReview();
}

function generateQuestionReview() {
    const reviewContainer = document.getElementById('questionReview');
    if (!reviewContainer || typeof questions === 'undefined') return;
    
    reviewContainer.innerHTML = '<h3>Question Review</h3>';
    
    questions.forEach((question, index) => {
        const userAnswer = userAnswers[index] || [];
        const correctAnswer = question.answer;
        
        // Determine if answer is correct
        let isCorrect = false;
        if (Array.isArray(correctAnswer)) {
            const sortedUserAnswer = [...userAnswer].sort();
            const sortedCorrectAnswer = [...correctAnswer].sort();
            isCorrect = JSON.stringify(sortedUserAnswer) === JSON.stringify(sortedCorrectAnswer);
        } else {
            isCorrect = userAnswer[0] === correctAnswer;
        }
        
        // Format answers for display
        const userAnswerDisplay = Array.isArray(userAnswer) && userAnswer.length > 0 
            ? userAnswer.join(', ') 
            : 'Not answered';
        
        const correctAnswerDisplay = Array.isArray(correctAnswer) 
            ? correctAnswer.join(', ') 
            : correctAnswer;
        
        const reviewItem = document.createElement('div');
        reviewItem.className = `review-item ${isCorrect ? 'correct' : 'incorrect'}`;
        reviewItem.innerHTML = `
            <div class="review-question">
                <strong>Question ${index + 1}:</strong> ${question.text.substring(0, 100)}...
            </div>
            <div class="review-answer">
                <span class="answer-label">Your Answer:</span> 
                <span class="answer-value">${userAnswerDisplay}</span>
            </div>
            <div class="review-correct">
                <span class="answer-label">Correct Answer:</span> 
                <span class="answer-value">${correctAnswerDisplay}</span>
            </div>
            <div class="review-status ${isCorrect ? 'status-correct' : 'status-incorrect'}">
                ${isCorrect ? '✓ Correct' : '✗ Incorrect'}
            </div>
        `;
        
        reviewContainer.appendChild(reviewItem);
    });
}

