// --- Session History (now PostgreSQL-backed, per signed-in user) ---
//
// Same synchronous API as before; we keep an in-memory cache hydrated from
// /api/history on sign-in and fire-and-forget writes to /api/history when
// the user finishes a session.
let historyCache = [];

async function bootstrapSessionHistory() {
    try {
        const r = await _authFetch('/api/history');
        if (r.ok && r.data && Array.isArray(r.data.history)) {
            historyCache = r.data.history.map(h => ({
                mode: h.mode,
                score: h.score,
                correct: h.correct,
                total: h.total,
                date: h.date ? new Date(h.date).toLocaleString() : '',
                setId: h.setId,
            }));
        } else {
            historyCache = [];
        }
    } catch (e) {
        console.warn('[history] bootstrap failed:', e);
        historyCache = [];
    }
}

function saveSessionHistory(result) {
    // Optimistic local push so renderSessionHistory paints immediately.
    historyCache.unshift(result);
    _authFetch('/api/history', {
        method: 'POST',
        body: JSON.stringify({
            mode: result.mode,
            score: result.score,
            correct: result.correct,
            total: result.total,
            setId: QSetStore.getActiveId() || null,
        }),
    }).catch((e) => console.warn('[history] append failed:', e));
}

function renderSessionHistory() {
    const historyList = document.getElementById('historyList');
    if (!historyList) return;

    if (!historyCache.length) {
        historyList.innerHTML = '<div style="color:#888;">No session history yet.</div>';
    } else {
        historyList.innerHTML = historyCache.map((h) => `
            <div style="padding:8px 0; border-bottom:1px solid #eee;">
                <strong>${h.mode}</strong> | Score: <b>${h.score}%</b> | Correct: ${h.correct}/${h.total} | Date: ${h.date}
            </div>
        `).join('');
    }

    // Incomplete session notice — still per-device via localStorage.
    const incompleteNotice = document.getElementById('incompleteSessionNotice');
    const sessionData = JSON.parse(localStorage.getItem('examSessionData') || '{}');
    if (incompleteNotice) {
        if (sessionData && sessionData.sessionActive) {
            incompleteNotice.style.display = 'block';
            const continueBtn = document.getElementById('continueButton');
            if (continueBtn) continueBtn.style.display = 'block';
        } else {
            incompleteNotice.style.display = 'none';
            const continueBtn = document.getElementById('continueButton');
            if (continueBtn) continueBtn.style.display = 'none';
        }
    }
}

function clearSessionHistory() {
    historyCache = [];
    _authFetch('/api/history', { method: 'DELETE' })
        .catch((e) => console.warn('[history] clear failed:', e));
    renderSessionHistory();
}

// --- Hook into exam/training completion ---

function submitExam() {
    clearInterval(timerInterval);
    calculateScore();

    // Save session result to history
    const correct = typeof lastScoreCorrectCount !== 'undefined' ? lastScoreCorrectCount : 0;
    const total = typeof questions !== 'undefined' ? questions.length : 0;
    const percentage = total ? Math.round((correct / total) * 100) : 0;
    const mode = isTrainingMode ? 'Training' : 'Exam';
    const now = new Date();
    const dateStr = now.toLocaleString();
    saveSessionHistory({
        mode: mode,
        score: percentage,
        correct: correct,
        total: total,
        date: dateStr
    });

    // Roll the per-set stats forward so the Question sets card shows progress.
    try {
        const activeSetId = QSetStore.getActiveId();
        if (activeSetId) QSetStore.updateStats(activeSetId, percentage);
    } catch (_) { /* localStorage may be disabled */ }

    if (isTrainingMode) {
        showFullscreenFeedback();
    } else {
        showResults();
    }

    sessionActive = false;
    saveToStorage();
    renderSessionHistory();
}

