// Modified saveToStorage to include mode information
function saveToStorage() {
    const examData = {
        currentQuestion: currentQuestion,
        userAnswers: userAnswers,
        timeLeft: timeLeft,
        isTrainingMode: isTrainingMode,
        isUnlimitedTime: isUnlimitedTime,
        sessionActive: sessionActive // <-- ensure this is true while in progress
    };
    localStorage.setItem('examSessionData', JSON.stringify(examData));
}

// Modified loadFromStorage to check for existing session
function loadFromStorage() {
    const savedData = localStorage.getItem('examSessionData');
    if (savedData) {
        try {
            const sessionData = JSON.parse(savedData);
            if (sessionData.sessionActive) {
                const continueButton = document.getElementById('continueButton');
                if (continueButton) {
                    continueButton.style.display = 'block';
                }
                // Show incomplete session notice
                const incompleteNotice = document.getElementById('incompleteSessionNotice');
                if (incompleteNotice) incompleteNotice.style.display = 'block';
            }
        } catch (e) {
            console.error('Error loading from storage:', e);
        }
    }
}

function clearStorage() {
    localStorage.removeItem('examSessionData');
    localStorage.removeItem('pythonExamData'); // Clean up old storage key
}

// Initialize on load
window.addEventListener('load', function() {
    loadFromStorage();
    const totalQuestionsEl = document.getElementById('totalQuestionsCount');
    if (totalQuestionsEl && typeof questions !== 'undefined') {
        totalQuestionsEl.textContent = questions.length;
    }
    renderSessionHistory();
});

// Save when leaving
window.addEventListener('beforeunload', saveToStorage);

// Handle visibility change (when user switches tabs)
document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
        saveToStorage();
    } else {
        loadFromStorage();
    }
});

// ---------------------------------------------------------------------------
// PDF upload → /api/generate (server.py)
// ---------------------------------------------------------------------------
let selectedPdfFile = null;
let analysisData = null;
let selectedQuestionCount = null;

function setUploadStatus(message, kind) {
    const el = document.getElementById('uploadStatus');
    if (!el) return;
    if (!message) {
        el.style.display = 'none';
        el.textContent = '';
        el.className = 'upload-status';
        return;
    }
    el.textContent = message;
    el.className = 'upload-status ' + (kind || '');
    el.style.display = 'block';
}

function isPdfFile(file) {
    if (!file) return false;
    if (file.type === 'application/pdf') return true;
    return /\.pdf$/i.test(file.name || '');
}

function resetAnalysisState() {
    analysisData = null;
    selectedQuestionCount = null;
    const panel = document.getElementById('analysisPanel');
    const loading = document.getElementById('analysisLoading');
    const result = document.getElementById('analysisResult');
    const hint = document.getElementById('chipHint');
    if (panel) panel.style.display = 'none';
    if (loading) loading.style.display = 'flex';
    if (result) result.style.display = 'none';
    if (hint) hint.textContent = '';
    document.querySelectorAll('#countChips .chip').forEach((chip) => {
        chip.classList.remove('chip--selected', 'chip--warn', 'chip--disabled');
        chip.disabled = false;
        chip.setAttribute('aria-checked', 'false');
        chip.removeAttribute('title');
    });
    updateGenerateButton();
}

function updateGenerateButton() {
    const btn = document.getElementById('uploadPdfBtn');
    if (!btn) return;
    if (isGenerationLimitReached()) {
        btn.disabled = true;
        btn.title = 'You have used all monthly generations for your current plan.';
        return;
    }
    btn.disabled = !(selectedPdfFile && analysisData && selectedQuestionCount);
    if (!btn.disabled) btn.removeAttribute('title');
}

function renderChips(analysis) {
    document.querySelectorAll('#countChips .chip').forEach((chip) => {
        const value = parseInt(chip.dataset.count, 10);
        chip.classList.remove('chip--selected', 'chip--warn', 'chip--disabled');
        chip.disabled = false;
        chip.setAttribute('aria-checked', 'false');

        if (value > analysis.max) {
            chip.classList.add('chip--disabled');
            chip.disabled = true;
            chip.title = 'Above this PDF’s recommended ceiling of ' + analysis.max + '.';
        } else if (value > analysis.recommendedHigh) {
            chip.classList.add('chip--warn');
            chip.title = 'Slightly above the suggested sweet spot ('
                + analysis.recommendedLow + '–' + analysis.recommendedHigh + ') — quality may dip.';
        } else {
            chip.title = 'Within the recommended range.';
        }
    });
}

function selectChip(chip) {
    if (chip.disabled || chip.classList.contains('chip--disabled')) return;
    document.querySelectorAll('#countChips .chip').forEach((c) => {
        c.classList.remove('chip--selected');
        c.setAttribute('aria-checked', 'false');
    });
    chip.classList.add('chip--selected');
    chip.setAttribute('aria-checked', 'true');
    selectedQuestionCount = parseInt(chip.dataset.count, 10);

    const hint = document.getElementById('chipHint');
    if (hint && analysisData) {
        if (selectedQuestionCount > analysisData.recommendedHigh) {
            hint.textContent = 'Heads up: this is above the suggested ceiling — some questions may feel thin.';
            hint.className = 'chip-hint chip-hint--warn';
        } else {
            hint.textContent = 'Good fit for this PDF.';
            hint.className = 'chip-hint chip-hint--ok';
        }
    }
    updateGenerateButton();
}

async function analyzePdf() {
    if (!selectedPdfFile) return;
    resetAnalysisState();

    const panel = document.getElementById('analysisPanel');
    const loading = document.getElementById('analysisLoading');
    const result = document.getElementById('analysisResult');
    if (panel) panel.style.display = 'block';

    const url = quizApiUrl('/api/analyze');
    const formData = new FormData();
    formData.append('pdf', selectedPdfFile);

    let response;
    try {
        response = await fetch(url, { method: 'POST', body: formData, credentials: 'include' });
    } catch (networkErr) {
        if (panel) panel.style.display = 'none';
        setUploadStatus(
            'Could not reach the backend at ' + url + '. Is server.py running? ('
            + networkErr.message + ')',
            'error'
        );
        return;
    }

    const bodyText = await response.text().catch(() => '');
    let data = null;
    try { data = bodyText ? JSON.parse(bodyText) : null; } catch (_) { /* non-JSON */ }

    if (!response.ok || !data || !data.ok) {
        if (panel) panel.style.display = 'none';
        const detail = (data && data.error) || (bodyText && bodyText.slice(0, 200)) || 'Analysis failed';
        setUploadStatus('Analysis failed: ' + detail, 'error');
        return;
    }

    analysisData = data;
    const msgEl = document.getElementById('analysisMessage');
    if (msgEl) msgEl.textContent = data.message;
    renderChips(data);

    if (loading) loading.style.display = 'none';
    if (result) result.style.display = 'block';
    updateGenerateButton();
}

function handlePdfSelection(file) {
    const nameEl = document.getElementById('selectedFileName');
    if (!file) {
        selectedPdfFile = null;
        if (nameEl) nameEl.textContent = '';
        resetAnalysisState();
        return;
    }
    if (!isPdfFile(file)) {
        selectedPdfFile = null;
        if (nameEl) nameEl.textContent = '';
        resetAnalysisState();
        setUploadStatus('Only PDF files are allowed.', 'error');
        return;
    }
    selectedPdfFile = file;
    if (nameEl) nameEl.textContent = 'Selected: ' + file.name;
    setUploadStatus('', '');
    resetAnalysisState();
    analyzePdf();
}

// ---------------------------------------------------------------------------
// Generation progress UI (driven by /api/generate/status polling)
// ---------------------------------------------------------------------------
const PHASE_LABELS = {
    queued:     'Queued',
    extracting: 'Reading PDF',
    chunking:   'Planning',
    generating: 'Generating',
    merging:    'Merging',
    writing:    'Saving',
    done:       'Done',
    error:      'Failed'
};

let progressElapsedTimer = null;
let progressStartedAt = 0;

function showGenerationProgress() {
    const panel = document.getElementById('generationProgress');
    const fill = document.getElementById('progressFill');
    const phase = document.getElementById('progressPhase');
    const elapsed = document.getElementById('progressElapsed');
    const msg = document.getElementById('progressMessage');
    if (!panel) return;
    panel.style.display = 'block';
    panel.classList.remove('gen-progress--done', 'gen-progress--error');
    if (fill) fill.style.width = '0%';
    if (phase) phase.textContent = 'Starting…';
    if (elapsed) elapsed.textContent = '0:00';
    if (msg) msg.textContent = 'Uploading PDF to the generator…';

    progressStartedAt = Date.now();
    if (progressElapsedTimer) clearInterval(progressElapsedTimer);
    progressElapsedTimer = setInterval(updateElapsedDisplay, 1000);
}

function updateElapsedDisplay() {
    const el = document.getElementById('progressElapsed');
    if (!el) return;
    const secs = Math.floor((Date.now() - progressStartedAt) / 1000);
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    el.textContent = m + ':' + (s < 10 ? '0' : '') + s;
}

function stopElapsedTimer() {
    if (progressElapsedTimer) {
        clearInterval(progressElapsedTimer);
        progressElapsedTimer = null;
    }
}

function hideGenerationProgress() {
    stopElapsedTimer();
    const panel = document.getElementById('generationProgress');
    if (panel) panel.style.display = 'none';
}

function applyJobToProgress(job) {
    const fill = document.getElementById('progressFill');
    const phase = document.getElementById('progressPhase');
    const msg = document.getElementById('progressMessage');
    const panel = document.getElementById('generationProgress');
    if (fill) fill.style.width = Math.max(0, Math.min(100, job.percent || 0)) + '%';
    if (phase) phase.textContent = PHASE_LABELS[job.phase] || job.phase || '';
    if (msg) msg.textContent = job.message || '';
    if (panel) {
        panel.classList.toggle('gen-progress--done', job.state === 'done');
        panel.classList.toggle('gen-progress--error', job.state === 'error');
    }
}

async function pollGenerationStatus(jobId) {
    const statusUrl = quizApiUrl('/api/generate/status/' + encodeURIComponent(jobId));
    const POLL_INTERVAL_MS = 800;
    let consecutiveNetworkErrors = 0;

    while (true) {
        let response;
        try {
            response = await fetch(statusUrl, { method: 'GET', credentials: 'include' });
        } catch (networkErr) {
            consecutiveNetworkErrors += 1;
            if (consecutiveNetworkErrors >= 5) {
                throw new Error('Lost contact with server while polling: ' + networkErr.message);
            }
            await sleep(POLL_INTERVAL_MS);
            continue;
        }
        consecutiveNetworkErrors = 0;

        const data = await response.json().catch(() => null);
        if (!response.ok || !data || !data.ok || !data.job) {
            const detail = (data && data.error) || ('HTTP ' + response.status);
            throw new Error('Status check failed: ' + detail);
        }

        const job = data.job;
        applyJobToProgress(job);

        if (job.state === 'done') return job;
        if (job.state === 'error') {
            const err = new Error(job.error || 'Generation failed.');
            err.job = job;
            throw err;
        }
        await sleep(POLL_INTERVAL_MS);
    }
}

function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

async function uploadPdf() {
    if (isGenerationLimitReached()) {
        setUploadStatus(
            'You have used all your monthly generations. Upgrade your plan to continue.',
            'error'
        );
        return;
    }

    if (!selectedPdfFile) {
        setUploadStatus('Please choose a PDF first.', 'error');
        return;
    }
    if (!selectedQuestionCount) {
        setUploadStatus('Pick how many questions to generate.', 'error');
        return;
    }

    const btn = document.getElementById('uploadPdfBtn');
    if (btn) btn.disabled = true;
    setUploadStatus('', '');
    showGenerationProgress();

    // The server now persists the generated set directly into PostgreSQL
    // owned by the current user (see JobManager._persist_set), so the old
    // localStorage hand-off is no longer needed. Keep this as a no-op for
    // any older code paths that still call setPendingSave.
    try {
        QSetStore.setPendingSave({
            filename: selectedPdfFile.name,
            requestedCount: selectedQuestionCount,
            analysis: analysisData ? {
                pageCount: analysisData.pageCount,
                wordCount: analysisData.wordCount,
                recommendedLow: analysisData.recommendedLow,
                recommendedHigh: analysisData.recommendedHigh
            } : null,
            timestamp: Date.now()
        });
    } catch (_) { /* localStorage may be disabled */ }

    const formData = new FormData();
    formData.append('pdf', selectedPdfFile);
    formData.append('count', String(selectedQuestionCount));

    const url = quizApiUrl('/api/generate');
    let response;
    try {
        response = await fetch(url, { method: 'POST', body: formData, credentials: 'include' });
    } catch (networkErr) {
        hideGenerationProgress();
        setUploadStatus(
            'Could not reach the backend at ' + url + '. Is server.py running? '
            + '(' + networkErr.message + ')',
            'error'
        );
        if (btn) btn.disabled = false;
        return;
    }

    // Read body as text first so non-JSON error pages (e.g. Apache 405 HTML) still surface.
    const bodyText = await response.text().catch(() => '');
    let data = null;
    try { data = bodyText ? JSON.parse(bodyText) : null; } catch (_) { /* not JSON */ }

    if (!response.ok || !data || !data.ok || !data.jobId) {
        hideGenerationProgress();
        const statusPart = response.status + (response.statusText ? ' ' + response.statusText : '');
        let detail;
        if (data && data.error) {
            detail = data.error;
            if (data.usage && currentUser) {
                currentUser.usage = data.usage;
                if (data.usage.planTier) currentUser.planTier = data.usage.planTier;
                paintUserPill();
                updateGenerateButton();
            }
        } else {
            const snippet = (bodyText || '').replace(/\s+/g, ' ').trim().slice(0, 200);
            detail = snippet || 'No response body';
        }
        setUploadStatus('Failed to start: ' + url + ' returned ' + statusPart + ' — ' + detail, 'error');
        if (btn) btn.disabled = false;
        return;
    }

    // Job started — poll for status.
    try {
        const finalJob = await pollGenerationStatus(data.jobId);
        stopElapsedTimer();
        setUploadStatus(finalJob.message || 'Questions generated. Reloading…', 'success');
        try { localStorage.removeItem('examSessionData'); } catch (_) {}
        setTimeout(() => window.location.reload(), 1100);
    } catch (err) {
        stopElapsedTimer();
        setUploadStatus('Failed: ' + err.message, 'error');
        if (btn) btn.disabled = false;
    }
}


// ===========================================================================
// Saved-set integration: hydrate active set, finalize a just-generated set,
// render the UI list, and provide activate/delete helpers.
// ===========================================================================

function activeQuestionsArray() {
    return (typeof questions !== 'undefined' && Array.isArray(questions)) ? questions : null;
}

function replaceLoadedQuestions(newList) {
    // `questions` is declared as `const` in questions.js — we can't reassign,
    // but we can mutate the array contents in place, which is what all the
    // quiz code reads through.
    const target = activeQuestionsArray();
    if (!target || !Array.isArray(newList)) return false;
    target.length = 0;
    for (const q of newList) target.push(q);
    return true;
}

function applyActiveSetIfAny() {
    const id = QSetStore.getActiveId();
    if (!id) return;
    const record = QSetStore.get(id);
    if (!record || !Array.isArray(record.questions) || !record.questions.length) return;
    replaceLoadedQuestions(record.questions);
}

function tryFinalizePendingSave() {
    const pending = QSetStore.getPendingSave();
    if (!pending) return;
    const loaded = activeQuestionsArray();
    if (!loaded || !loaded.length) return;

    try {
        const filename = pending.filename || '';
        const title = filename
            ? filename.replace(/\.pdf$/i, '').replace(/[_-]+/g, ' ').trim() || filename
            : 'Generated set';

        // Deep-copy questions so subsequent in-memory mutations can't change the saved copy.
        const snapshot = loaded.map(q => ({
            number: q.number,
            text: q.text,
            choices: Object.assign({}, q.choices || {}),
            answer: Array.isArray(q.answer) ? q.answer.slice() : [q.answer],
            maxSelections: q.maxSelections || 1
        }));

        const analysis = pending.analysis || {};
        const record = QSetStore.save({
            title: title,
            ownerId: null,
            source: {
                type: 'pdf-generated',
                filename: filename || null,
                pageCount: analysis.pageCount || null,
                wordCount: analysis.wordCount || null,
                requestedCount: pending.requestedCount || null,
                producedCount: snapshot.length,
                generatorModel: pending.generatorModel || null,
                generatedAt: pending.timestamp ? new Date(pending.timestamp).toISOString() : null
            },
            questions: snapshot,
            stats: { sessionsRun: 0, lastPlayedAt: null, bestScore: null, averageScore: null }
        });
        if (record) QSetStore.setActiveId(record.id);
    } catch (e) {
        console.warn('[QSetStore] failed to finalize pending save:', e);
    } finally {
        QSetStore.clearPendingSave();
    }
}

function renderQuestionSets() {
    const listEl = document.getElementById('questionSetsList');
    if (!listEl) return;
    listEl.innerHTML = '';

    const sets = QSetStore.list();
    const activeId = QSetStore.getActiveId();

    if (!sets.length) {
        const p = document.createElement('p');
        p.className = 'qsets-empty';
        p.textContent = 'No saved sets yet. Generate a question set from a PDF and it will be saved here automatically.';
        listEl.appendChild(p);
        return;
    }

    for (const s of sets) {
        const isActive = s.id === activeId;
        const item = document.createElement('article');
        item.className = 'qset-item' + (isActive ? ' qset-item--active' : '');
        item.dataset.id = s.id;

        const main = document.createElement('div');
        main.className = 'qset-item__main';

        const title = document.createElement('h4');
        title.className = 'qset-item__title';
        title.textContent = s.title || 'Untitled set';

        const sub = document.createElement('p');
        sub.className = 'qset-item__sub';
        const parts = [(s.questionCount || 0) + ' questions'];
        if (s.createdAt) {
            try { parts.push(new Date(s.createdAt).toLocaleDateString()); } catch (_) {}
        }
        if (s.bestScore != null) parts.push('Best ' + s.bestScore + '%');
        sub.textContent = parts.join(' · ');

        main.appendChild(title);
        main.appendChild(sub);

        const actions = document.createElement('div');
        actions.className = 'qset-item__actions';

        if (isActive) {
            const badge = document.createElement('span');
            badge.className = 'qset-item__badge';
            badge.textContent = 'Active';
            actions.appendChild(badge);
        } else {
            const useBtn = document.createElement('button');
            useBtn.type = 'button';
            useBtn.className = 'btn btn--secondary btn--sm';
            useBtn.textContent = 'Use';
            useBtn.addEventListener('click', () => activateQuestionSet(s.id));
            actions.appendChild(useBtn);
        }

        const delBtn = document.createElement('button');
        delBtn.type = 'button';
        delBtn.className = 'btn btn--ghost-danger btn--sm';
        delBtn.textContent = 'Delete';
        delBtn.setAttribute('aria-label', 'Delete ' + (s.title || 'set'));
        delBtn.addEventListener('click', () => deleteQuestionSet(s.id));
        actions.appendChild(delBtn);

        item.appendChild(main);
        item.appendChild(actions);
        listEl.appendChild(item);
    }
}

function activateQuestionSet(id) {
    const record = QSetStore.get(id);
    if (!record) return;
    QSetStore.setActiveId(id);
    // The questions array we'll load is structurally different from any in-flight
    // session, so drop the in-progress state (history is preserved).
    try { localStorage.removeItem('examSessionData'); } catch (_) {}
    // Reload so questions.js loads cleanly and DOMContentLoaded re-hydrates from the new active set.
    window.location.reload();
}

function deleteQuestionSet(id) {
    const summaries = QSetStore.list();
    const summary = summaries.find(s => s.id === id);
    if (!summary) return;
    const ok = window.confirm('Delete "' + (summary.title || 'this set') + '"? This cannot be undone.');
    if (!ok) return;
    const wasActive = QSetStore.getActiveId() === id;
    QSetStore.delete(id);
    renderQuestionSets();
    if (wasActive) {
        // Drop the in-flight session and reload — the next active source becomes
        // whatever questions.js holds on disk (the last generation, or the demo bank).
        try { localStorage.removeItem('examSessionData'); } catch (_) {}
        window.location.reload();
    }
}


document.addEventListener('DOMContentLoaded', () => {
    // Auth-gate the dashboard. checkAuthOnLoad() either:
    //   • shows the sign-in overlay, OR
    //   • hides it, hydrates QSetStore from PostgreSQL for the signed-in user,
    //     swaps the active set into `questions`, and paints the sets list.
    checkAuthOnLoad().catch(e => {
        console.warn('[auth] checkAuthOnLoad failed:', e);
        showAuthOverlay();
    });

    const dropZone = document.getElementById('dropZone');
    const fileInput = document.getElementById('pdfFileInput');
    if (!dropZone || !fileInput) return;

    dropZone.addEventListener('click', () => fileInput.click());
    dropZone.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
            e.preventDefault();
            fileInput.click();
        }
    });
    fileInput.addEventListener('change', (e) => {
        const file = e.target.files && e.target.files[0];
        handlePdfSelection(file);
    });

    document.querySelectorAll('#countChips .chip').forEach((chip) => {
        chip.addEventListener('click', () => selectChip(chip));
        chip.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
                e.preventDefault();
                selectChip(chip);
            }
        });
    });

    ['dragenter', 'dragover'].forEach((evt) => {
        dropZone.addEventListener(evt, (e) => {
            e.preventDefault();
            e.stopPropagation();
            dropZone.classList.add('dragover');
        });
    });
    ['dragleave', 'dragend'].forEach((evt) => {
        dropZone.addEventListener(evt, (e) => {
            e.preventDefault();
            e.stopPropagation();
            dropZone.classList.remove('dragover');
        });
    });
    dropZone.addEventListener('drop', (e) => {
        e.preventDefault();
        e.stopPropagation();
        dropZone.classList.remove('dragover');
        const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
        handlePdfSelection(file);
    });

    // Prevent the browser from navigating to a dropped file if the user misses the zone.
    window.addEventListener('dragover', (e) => e.preventDefault());
    window.addEventListener('drop', (e) => e.preventDefault());
});
